<?php declare(strict_types=1); $base=config('app.base_path'); $isTrash=!empty($trash); ?>
<div class="page-header"><div><h1><?= $isTrash?'Deleted Fresh Food Products':'Fresh Food Products' ?></h1><p>Manage prices, discounts, units, quantities and availability.</p></div><div class="page-actions"><?php if($isTrash): ?><a class="btn btn-secondary" href="<?= $base ?>/fresh-food/products">Active Products</a><?php else: ?><a class="btn btn-secondary" href="<?= $base ?>/fresh-food/products?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/fresh-food/products/create">Add Product</a><?php endif; ?></div></div>
<div class="card"><table class="table"><thead><tr><th>Business</th><th>Product</th><th>Category</th><th>Price</th><th>Discount</th><th>Selling Price</th><th>Availability</th><th>Action</th></tr></thead><tbody>
<?php if(empty($products)): ?><tr><td colspan="8"><div class="empty-state">No products found.</div></td></tr><?php else: foreach($products as $p): $price=(float)$p['price'];$dv=(float)($p['discount_value']??0);$dt=$p['discount_type']??'NONE';$disc=$dt==='PERCENT'?min($price,$price*$dv/100):($dt==='FLAT'?min($price,$dv):0);$sell=$price-$disc; ?><tr><td><?= htmlspecialchars((string)$p['business_name'],ENT_QUOTES,'UTF-8') ?></td><td><strong><?= htmlspecialchars((string)$p['name'],ENT_QUOTES,'UTF-8') ?></strong><?= !empty($p['is_variable_weight'])?' <small>(variable weight)</small>':'' ?></td><td><?= htmlspecialchars((string)($p['category_name']??'—'),ENT_QUOTES,'UTF-8') ?></td><td>₹<?= number_format($price,2) ?>/<?= htmlspecialchars((string)$p['unit'],ENT_QUOTES,'UTF-8') ?></td><td><?= $dt==='PERCENT'?number_format($dv,2).'%':($dt==='FLAT'?'₹'.number_format($dv,2):'—') ?></td><td>₹<?= number_format($sell,2) ?>/<?= htmlspecialchars((string)$p['unit'],ENT_QUOTES,'UTF-8') ?></td><td><?= !empty($p['is_available'])?'Available':'Unavailable' ?></td><td><?php if($isTrash): ?><form method="post" action="<?= $base ?>/fresh-food/products/<?= (int)$p['id'] ?>/restore"><button class="btn btn-secondary">Restore</button></form><?php else: ?><a class="link-button" href="<?= $base ?>/fresh-food/inventory/adjust?product_id=<?= (int)$p['id'] ?>">Inventory</a> <a class="link-button" href="<?= $base ?>/fresh-food/inventory/<?= (int)$p['id'] ?>/movements">History</a> <a class="link-button" href="<?= $base ?>/fresh-food/products/<?= (int)$p['id'] ?>/edit">Edit</a> <form method="post" action="<?= $base ?>/fresh-food/products/<?= (int)$p['id'] ?>/delete" style="display:inline"><button class="link-button" onclick="return confirm('Delete this product?')">Delete</button></form><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div>
